operation.add:
if ($this->config->get('yespo_site_script')) {
	$yespo_site_script = $this->config->get('yespo_site_script');
	if (!empty($yespo_site_script)) {
		$data['yespo_site_script'] = html_entity_decode($yespo_site_script);
	}
	$yespo_web_push_script = $this->config->get('yespo_web_push_script');
	if (!empty($yespo_web_push_script)) {
		$data['yespo_web_push_script'] = html_entity_decode($yespo_web_push_script);
	}
	$route = !empty($this->request->get['route']) ? $this->request->get['route'] : '';
	$begin_checkout_routes = [
		'checkout/cart',
		'checkout/checkout',
		'checkout/simplecheckout',
		'checkout/unicheckout',
		'checkout/uni_checkout',
		'checkout/revcheckout',
		'revolution/revcheckout',
		'checkout/oct_fastorder',
		'checkout/fastorder',
		'checkout/onepcheckout',
		'checkout/checkout_two_step',
		'extension/module/buy',
		'checkout/buy',
		'extension/quickcheckout/checkout',
		'lightcheckout/checkout',
		'extension/module/custom',
		'tmdqc/tmdcheckout',
		'quickcheckout/checkout',
	];
	if (in_array($route, $begin_checkout_routes)) {
		$data['yespo_event'] = "<script>document.addEventListener('DOMContentLoaded', function() {if (typeof eS === 'function') { eS('sendEvent', 'StatusCartPage'); }})</script>";
	}
	if (in_array($route, ['common/home', ''])) {
		$data['yespo_event'] = "<script>document.addEventListener('DOMContentLoaded', function() {if (typeof eS === 'function') { eS('sendEvent', 'MainPage'); }})</script>";
	}
	if (in_array($route, ['error/not_found'])) {
		$data['yespo_event'] = "<script>document.addEventListener('DOMContentLoaded', function() {if (typeof eS === 'function') { eS('sendEvent', 'NotFound'); }})</script>";
	}
	if (isset($this->session->data['customer_id']) && empty($this->session->data['yespo_customer_data'])) {
		$this->load->model('extension/module/yespo');
		$this->model_extension_module_yespo->sendCustomerData();
		$this->session->data['yespo_customer_data'] = true;
	}
	if (!empty($this->session->data['yespo_customer_data_event']) && is_array($this->session->data['yespo_customer_data_event'])) {
		$data['yespo_customer_data'] = "<script>document.addEventListener('DOMContentLoaded', function() {if (typeof eS === 'function') { eS('sendEvent', 'CustomerData', " . json_encode(['CustomerData' => $this->session->data['yespo_customer_data_event']], JSON_UNESCAPED_UNICODE) . "); }})</script>";
		unset($this->session->data['yespo_customer_data_event']);
	}
}

{% if yespo_site_script %}{{ yespo_site_script }}{% endif %}
{% if yespo_web_push_script %}{{ yespo_web_push_script }}{% endif %}
{% if yespo_event %}{{ yespo_event }}{% endif %}
{% if yespo_event %}{{ yespo_event }}{% endif %}
{% if yespo_customer_data %}{{ yespo_customer_data }}{% endif %}

{% if yespo_event %}
<script>
if (typeof eS !== 'undefined') {
	product_page_event = {{ yespo_event }};
	eS('sendEvent', 'ProductPage', product_page_event);
}			
</script>
{% endif %}

